# FastAPI app server that stays stateless.
# Session data lives in Redis, shared by every server copy.
import os, redis
from fastapi import FastAPI, Header

app = FastAPI()
store = redis.Redis.from_url(os.environ["REDIS_URL"])  # shared, not local memory

@app.get("/health")                 # the load balancer calls this every few seconds
def health():
    return {"ok": True}

@app.get("/me")
def me(session_id: str = Header(...)):
    user = store.get(f"session:{session_id}")   # works on ANY server copy
    return {"user": user.decode() if user else None}

from collections import deque

def balanced(expr: str) -> bool:
    pairs = {")": "(", "]": "[", "}": "{"}
    stack = []
    for ch in expr:
        if ch in "([{":
            stack.append(ch)                       # push opener
        elif ch in pairs:
            if not stack or stack.pop() != pairs[ch]:
                return False                       # wrong or missing opener
    return not stack                               # nothing left open

print(balanced("(load > 5 and [zone in {A, B}])"))  # True
print(balanced("(a and [b)]"))                      # False

tickets = deque(["T-101", "T-102"])
tickets.append("T-103")                            # arrive at the back
print(tickets.popleft())                           # T-101 served first, O(1)

from collections import deque
import heapq

callers = {                        # service -> services that call it
    "pricing": ["checkout", "quotes"],
    "checkout": ["web"], "quotes": ["web", "partner-api"],
    "web": [], "partner-api": [],
}

def bfs(start: str) -> dict[str, int]:
    dist = {start: 0}
    q = deque([start])
    while q:
        node = q.popleft()
        for nxt in callers[node]:
            if nxt not in dist:            # visited check
                dist[nxt] = dist[node] + 1
                q.append(nxt)
    return dist

print(bfs("pricing"))  # {'pricing': 0, 'checkout': 1, 'quotes': 1, 'web': 2, 'partner-api': 2}

latency_ms = {"/search": 840, "/login": 95, "/export": 2300, "/cart": 180}
print(heapq.nlargest(2, latency_ms.items(), key=lambda kv: kv[1]))
