const input  = document.querySelector("#q");
const button = document.querySelector("#ask");
const out    = document.querySelector("#answer");

button.disabled = true;

input.addEventListener("input", () => {
  button.disabled = input.value.trim() === "";   // no empty questions
});

button.addEventListener("click", () => {
  const question = input.value.trim();
  out.textContent = `You asked: ${question}`;    // textContent, never innerHTML
});

// types.ts
interface Source {
  title: string;
  url: string;
}

interface AskResponse {
  answer: string;
  sources: Source[];          // an array of Source objects
  confidence?: number;        // ? means optional
}

function render(res: AskResponse): string {
  const list = res.sources.map((s) => `- ${s.title}`).join("\n");
  return `${res.answer}\n\nSources:\n${list}`;
}

