// app.js (calls our own backend, which holds the API key)
const API = "http://localhost:8000";

async function ask(question) {
  out.textContent = "Thinking...";                     // loading state
  button.disabled = true;
  try {
    const res = await fetch(`${API}/ask`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ question }),
    });
    if (!res.ok) throw new Error(`Server said ${res.status}`);  // 4xx/5xx
    const data = await res.json();
    out.textContent = data.answer + "\n\n" +
      data.sources.map((s) => "- " + s.title).join("\n");
  } catch (err) {
    out.textContent = "Sorry, something went wrong: " + err.message;
  } finally {
    button.disabled = false;
  }
}

button.addEventListener("click", () => ask(input.value.trim()));

// AskBox.tsx
import { useState } from "react";

type Props = { apiUrl: string };

export function AskBox({ apiUrl }: Props) {
  const [question, setQuestion] = useState("");
  const [answer, setAnswer] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);

  async function ask() {
    setLoading(true);
    const res = await fetch(`${apiUrl}/ask`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ question }),
    });
    const data = await res.json();
    setAnswer(data.answer);               // state change -> React re-renders
    setLoading(false);
  }

  return (
    <div>
      <input value={question} onChange={(e) => setQuestion(e.target.value)} />
      <button onClick={ask} disabled={loading || !question}>Ask</button>
      {loading ? <p>Thinking...</p> : answer && <p>{answer}</p>}
    </div>
  );
}
